async function uploadChartImage(file) {
  const ext = file.name.split(".").pop() || "jpg";
  const filename = `${Date.now()}-${Math.round(Math.random() * 1e6)}.${ext}`;
  const res = await fetch(`${SUPABASE_URL}/storage/v1/object/senales-imagenes/${filename}`, {
    method: "POST",
    headers: {
      apikey: SUPABASE_ANON_KEY,
      Authorization: `Bearer ${SUPABASE_ANON_KEY}`,
      "Content-Type": file.type || "application/octet-stream",
    },
    body: file,
  });
  if (!res.ok) {
    throw new Error(`Error ${res.status} al subir la imagen`);
  }
  return `${SUPABASE_URL}/storage/v1/object/public/senales-imagenes/${filename}`;
}

async function createSignal(payload) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/signals`, {
    method: "POST",
    headers: {
      apikey: SUPABASE_ANON_KEY,
      Authorization: `Bearer ${SUPABASE_ANON_KEY}`,
      "Content-Type": "application/json",
      Prefer: "return=representation",
    },
    body: JSON.stringify(payload),
  });
  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`Error ${res.status} al crear la señal ${text}`);
  }
  return res.json();
}

async function updateSignal(id, payload) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/signals?id=eq.${id}`, {
    method: "PATCH",
    headers: {
      apikey: SUPABASE_ANON_KEY,
      Authorization: `Bearer ${SUPABASE_ANON_KEY}`,
      "Content-Type": "application/json",
      Prefer: "return=representation",
    },
    body: JSON.stringify(payload),
  });
  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`Error ${res.status} al actualizar la señal ${text}`);
  }
  return res.json();
}

async function fetchSignals() {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/signals?select=*&order=created_at.desc`, {
    headers: {
      apikey: SUPABASE_ANON_KEY,
      Authorization: `Bearer ${SUPABASE_ANON_KEY}`,
    },
  });
  if (!res.ok) {
    throw new Error(`Error ${res.status} al leer las señales`);
  }
  const rows = await res.json();
  return rows.map((r) => ({
    id: r.id,
    par: r.par,
    direccion: r.direccion,
    estado: r.estado,
    pips: r.pips,
    entrada: Number(r.precio_entrada),
    sl: Number(r.stop_loss),
    tp: Number(r.take_profit),
    tipoOrden: r.tipo_orden,
    autor: r.autor,
    imagenUrl: r.imagen_url,
    fecha: r.created_at
      ? new Date(r.created_at).toLocaleString("es-AR", { dateStyle: "medium", timeStyle: "short" })
      : "",
  }));
}

